LANGS = ['en','de','fr','it','es','ru','uk']; DIRS = {'en':'values'}
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'app', 'src', 'main', 'res')
for i, l in enumerate(LANGS):
    d = os.path.join(root, DIRS.get(l, 'values-' + l)); os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, 'strings.xml'), 'w', encoding='utf-8') as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n')
        for k, v in S.items():
            t = escape(v[i]).replace("'", "\\'")
            f.write('    <string name="%s"%s>%s</string>\n' % (k, ' translatable="false"' if k == 'app_name' else '', t))
        f.write('</resources>\n')
with open(os.path.join(root, 'xml', 'locales_config.xml'), 'w') as f:
    f.write('<?xml version="1.0" encoding="utf-8"?>\n<locale-config xmlns:android="http://schemas.android.com/apk/res/android">\n' + ''.join('    <locale android:name="%s"/>\n' % l for l in LANGS) + '</locale-config>\n')
print(len(S), 'strings x', len(LANGS))
